  (md5($fold$fold-protocol:dyslipidemia$fold$)::uuid, $fold$Dyslipidemia$fold$, $fold$Fold$fold$, ARRAY[$fold$Hyperlipidemia$fold$]::text[], '{}', $fold$Fold Health$fold$, $fold$2026.1$fold$,
   'active', 'fold', 'Fold clinical content', $fold${"schemaVersion":1,"summary":"Risk-based statin therapy follow-through, LDL-C response checks, side-effect support and heart-healthy lifestyle.","scope":{"conditions":[{"name":"Hyperlipidemia","code":null}],"population":null,"exclusions":[]},"thresholds":[{"id":"t1","measure":"LDL-C","comparator":">=","value":190,"value2":null,"unit":"mg/dL","label":"Severe hypercholesterolemia","action":"Flag for high-intensity statin review (ages 20–75).","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"t2","measure":"LDL-C on maximally tolerated statin, with clinical ASCVD","comparator":">=","value":70,"value2":null,"unit":"mg/dL","label":"Very high risk above threshold","action":"Flag for clinician review of adding a non-statin (such as ezetimibe).","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"t3","measure":"10-year ASCVD risk","comparator":">=","value":7.5,"value2":null,"unit":"%","label":"Intermediate or higher risk","action":"Prompt a statin discussion with the clinician if not on one.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"t4","measure":"Triglycerides (fasting)","comparator":">=","value":500,"value2":null,"unit":"mg/dL","label":"Severe hypertriglyceridemia","action":"Flag to the clinician the same week.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null}],"decisionRules":[{"id":"r1","when":"Diabetes, age 40–75, and not on a statin","then":"Flag for moderate-intensity statin review regardless of estimated risk.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"r2","when":"LDL-C falls less than expected after a statin start or change (under 50% on high-intensity, 30–49% on moderate-intensity)","then":"Review adherence first, then flag to the treating clinician for intensification review.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"r3","when":"Muscle aches or weakness on a statin","then":"Ask the patient not to stop on their own; notify the clinician to assess statin-associated muscle symptoms.","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null}],"cadence":[{"id":"c1","activity":"Lipid panel","kind":"lab","times":1,"every":3,"unit":"month","appliesWhen":"4–12 weeks after starting or changing lipid therapy","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"c2","activity":"Lipid panel","kind":"lab","times":1,"every":1,"unit":"year","appliesWhen":"Stable on therapy (every 3–12 months as needed)","source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null},{"id":"c3","activity":"Adherence and refill check","kind":"medication_review","times":1,"every":1,"unit":"month","appliesWhen":null,"source":"Fold care-management practice","page":null},{"id":"c4","activity":"Lifestyle coaching check-in","kind":"check_in","times":1,"every":1,"unit":"month","appliesWhen":null,"source":"Fold care-management practice","page":null}],"titration":[],"crossReferences":[{"id":"x1","title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","kind":"guideline","citation":null,"source":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol","page":null}]}$fold$::jsonb, $fold${"fold":{"slug":"dyslipidemia"}}$fold$::jsonb, 'Fold', 'Fold', now())
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  organization = EXCLUDED.organization,
  condition_tags = EXCLUDED.condition_tags,
  author = EXCLUDED.author,
  version = EXCLUDED.version,
  source_kind = EXCLUDED.source_kind,
  source_name = EXCLUDED.source_name,
  protocol = EXCLUDED.protocol,
  parse_meta = EXCLUDED.parse_meta,
  updated_at = CASE
    WHEN (clinical_protocols.title, clinical_protocols.version, clinical_protocols.protocol)
      IS DISTINCT FROM (EXCLUDED.title, EXCLUDED.version, EXCLUDED.protocol)
    THEN now() ELSE clinical_protocols.updated_at END;

-- Templates adapted from a Fold pathway now point at its protocol, keeping
-- the version they came from so a newer protocol shows as an update.
UPDATE public.care_plan_templates t
SET source_protocol = jsonb_build_object(
  'id', p.id, 'title', p.title, 'version', coalesce(t.source_pathway->>'version', p.version), 'organization', 'Fold')
FROM public.clinical_protocols p
WHERE t.source_protocol IS NULL
  AND t.source_pathway ? 'id'
  AND p.id = md5('fold-protocol:' || (t.source_pathway->>'id'))::uuid;

-- One starter template per Fold protocol.
WITH src AS (
